using IptvManagement.Domain.Entities; using IptvManagement.Infrastructure.Identity; using Microsoft.AspNetCore.Identity.EntityFrameworkCore; using Microsoft.EntityFrameworkCore;
namespace IptvManagement.Infrastructure.Data;
public class AppDbContext(DbContextOptions<AppDbContext> options):IdentityDbContext<ApplicationUser>(options){ public DbSet<Customer> Customers=>Set<Customer>(); public DbSet<Subscription> Subscriptions=>Set<Subscription>(); public DbSet<SubscriptionPackage> Packages=>Set<SubscriptionPackage>(); public DbSet<Device> Devices=>Set<Device>(); public DbSet<Channel> Channels=>Set<Channel>(); public DbSet<ChannelCategory> Categories=>Set<ChannelCategory>(); public DbSet<PackageChannel> PackageChannels=>Set<PackageChannel>(); public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<Invoice> Invoices=>Set<Invoice>(); public DbSet<AuditLog> AuditLogs=>Set<AuditLog>(); public DbSet<PlaylistAccessLog> PlaylistAccessLogs=>Set<PlaylistAccessLog>(); public DbSet<SystemSetting> SystemSettings=>Set<SystemSetting>(); public DbSet<DeviceActivationCode> DeviceActivationCodes=>Set<DeviceActivationCode>(); protected override void OnModelCreating(ModelBuilder b){ base.OnModelCreating(b); b.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly); } }
